approaches.pseudocode:
positions = empty map
for i from 0 to n-1:
  if target - values[i] exists in positions:
    return [positions[target - values[i]], i]
  positions[values[i]] = i
return []

for i from 0 to n-1:
  for j from i+1 to n-1:
    if values[i]+values[j] == target: return [i,j]
return []

best = -infinity
for start in positions:
  sum = 0
  for end from start to n-1:
    sum += values[end]; best = max(best,sum)
return best

left = 0; right = n - 1
while left <= right:
  mid = floor((left + right)/2)
  if values[mid] == target: return mid
  if left half is sorted:
    keep left half if values[left] <= target < values[mid]
  else:
    keep right half if values[mid] < target <= values[right]
return -1

left = 0; best = 0; last = empty map
for right from 0 to n-1:
  if text[right] was seen: left = max(left, last[text[right]] + 1)
  last[text[right]] = right
  best = max(best, right-left+1)
return best

answers = n zeros; stack = []
for i from 0 to n-1:
  while stack nonempty and temperatures[stack.top] < temperatures[i]:
    j = pop; answers[j] = i-j
  push i
return answers

depth(node):
  if node is null: return 0
  return 1 + max(depth(node.left), depth(node.right))

valid(node, lower, upper):
  if node is null: return true
  if not lower < node.value < upper: return false
  return valid(node.left,lower,node.value) and valid(node.right,node.value,upper)
return valid(root,-infinity,+infinity)

count = 0
for every cell:
  if cell is unvisited land:
    count += 1
    flood all orthogonally connected land, marking visited
return count

result = [[]]
for value in values:
  oldSize = result.size
  for i from 0 to oldSize-1:
    append result[i] + [value]
return result

dp[0] = 0; all other entries = infinity
for subtotal from 1 to amount:
  for coin <= subtotal:
    dp[subtotal] = min(dp[subtotal], dp[subtotal-coin]+1)
return -1 if dp[amount] is infinity else dp[amount]

dp = n ones
for i from 0 to n-1:
  for j from 0 to i-1:
    if values[j] < values[i]: dp[i] = max(dp[i],dp[j]+1)
return max(dp), or 0 when empty

previous = zeros(length(second)+1)
for character in first:
  current[0] = 0
  for j from 1 to length(second):
    if character == second[j-1]: current[j] = previous[j-1]+1
    else: current[j] = max(previous[j],current[j-1])
  previous = current
return previous.last

dp[0] = true; all others false
for end from 1 to text.length:
  for word in words:
    if word fits and dp[end-word.length] and text suffix matches word:
      dp[end] = true; break
return dp[text.length]
